// npm install express ；运行：node app.js
const express = require("express");
const app = express();

app.use(express.json());            // 框架内置中间件：解析 JSON 请求体

// 你只注册处理函数，何时调用由框架决定（控制反转）
app.get("/api/health", (req, res) => {
  res.json({ ok: true });
});

app.post("/api/echo", (req, res) => {
  if (!req.body?.text) {
    return res.status(400).json({ error: "text is required" });
  }
  res.json({ echo: req.body.text });
});

// 错误处理中间件：四个参数是 Express 的约定
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: "internal error" });
});

app.listen(3000, () => console.log("http://localhost:3000"));

// npm install zod
import { z } from "zod";

const SignupSchema = z.object({
  email: z.string().trim().toLowerCase().email().max(254),
  name: z.string().trim().min(1).max(50),
  age: z.number().int().min(13).max(120),
  plan: z.enum(["free", "pro"]),          // 白名单取值
}).strict();                              // 拒绝多余字段，防批量赋值

export function handleSignup(body: unknown) {
  const result = SignupSchema.safeParse(body);
  if (!result.success) {
    // 返回 400 与字段级错误，不回显原始可疑输入
    return { status: 400, errors: result.error.flatten().fieldErrors };
  }
  const data = result.data;               // 类型安全、已规范化的数据
  // 后续数据库操作仍需参数化查询
  return { status: 201, data };
}
